			b.WriteByte(',')
		}
		b.WriteRune(r)
	}
	return b.String()
}

func currencySymbol(currency string) (string, error) {
	switch currency {
	case "USD":
		return "$", nil
	case "EUR":
		return "€", nil
	default:
		return "", errors.New("invalid currency")
	}
}
